{
  "title": "Silent Wake",
  "description": "Naval cyber-kinetic escalation \u2014 15-turn simple collaborative exercise. Naval Group, February 2026.",
  "content": {
    "game_mode": "simple_collaborative",
    "game_mode_config": {
      "base_decision_time_ms": 300000
    },
    "default_time_factor": 1.0,
    "briefing": "You are the crew of a Frigate on independent transit to patrol sector Alpha-3. NLT 112000B arrival. Transit time approx. 6 hrs at planned speed 15 kts. Regional posture: heightened readiness. ROE: Weapons Tight. Intelligence indicates possible hostile naval presence in theatre with potential use of visual and electronic deception tactics. No escort assigned. All systems nominal. Organic helicopter joins upon arrival.",
    "objectives": [
      "Maintain mission tempo through escalating anomalies",
      "Identify and respond to AIS spoofing and cyber intrusion",
      "Manage combat systems degradation under kinetic threat",
      "Neutralise the hostile surface unit",
      "Transition to post-crisis control with minimal residual risk"
    ],
    "roles": [
      {
        "id": "co",
        "label": "Commanding Officer",
        "player_type": "decision_maker"
      },
      {
        "id": "ops",
        "label": "Operations Officer",
        "player_type": "advisor"
      },
      {
        "id": "nav",
        "label": "Navigator",
        "player_type": "advisor"
      },
      {
        "id": "eo",
        "label": "Engineering Officer",
        "player_type": "advisor"
      },
      {
        "id": "cyop",
        "label": "Cyber Operations Officer",
        "player_type": "advisor"
      },
      {
        "id": "aawo",
        "label": "Anti-Air Warfare Officer",
        "player_type": "advisor"
      },
      {
        "id": "pwo",
        "label": "Principal Warfare Officer",
        "player_type": "advisor"
      }
    ],
    "phases": [
      {
        "id": "phase-transit",
        "title": "Transit Phase",
        "description": "Turns 1\u20133: In transit with emerging anomalies.",
        "events": [
          "evt-t1",
          "evt-t2",
          "evt-t3"
        ]
      },
      {
        "id": "phase-cyber-detect",
        "title": "Cyber Detection",
        "description": "Turns 4\u20136: AIS spoofing confirmed, hostile contact, cyber signal.",
        "events": [
          "evt-t4",
          "evt-t5",
          "evt-t6"
        ]
      },
      {
        "id": "phase-escalation",
        "title": "Escalation",
        "description": "Turns 7\u20139: AAW malfunction, air threat, hostile salvo.",
        "events": [
          "evt-t7",
          "evt-t8",
          "evt-t9"
        ]
      },
      {
        "id": "phase-combat",
        "title": "Combat",
        "description": "Turns 10\u201312: First hit, cyber root cause, new cyber alert.",
        "events": [
          "evt-t10",
          "evt-t11",
          "evt-t12"
        ]
      },
      {
        "id": "phase-recovery",
        "title": "Recovery",
        "description": "Turns 13\u201315: Hard choices, surface threat neutralised, end state.",
        "events": [
          "evt-t13",
          "evt-t14",
          "evt-t15"
        ]
      }
    ],
    "events": [
      {
        "id": "evt-t1",
        "title": "Turn 1 \u2014 In Transit",
        "description": "Transit proceeding as planned. All systems nominal. No contacts of concern. EMCON: Navigation radar only.",
        "event_type": "decision",
        "scheduled_pt_ms": 0,
        "triggered_issues": [
          "iss-transit-nominal"
        ],
        "target_roles": [],
        "role_descriptions": {
          "ops": "Transit proceeding as planned. Estimated time to patrol sector unchanged. No updated intelligence from MTC. No declared maritime safety broadcasts affecting corridor. EMCON: Navigation radar only.",
          "nav": "Course and speed steady at 15 kts. No deviation from planned route. Commercial traffic density within expected levels. ETA to patrol area: 5 hours. Visibility ~12 nm.",
          "eo": "Radar performance nominal. Surface and air picture stable. No sensor anomalies observed. Communications functioning within expected parameters.",
          "cyop": "Network traffic baseline unchanged. No alerts. Routine monitoring only.",
          "aawo": "Air picture normal. No contacts of concern.",
          "pwo": "Surface picture normal. No contacts of concern."
        }
      },
      {
        "id": "evt-t2",
        "title": "Turn 2 \u2014 Subtle Anomalies",
        "description": "Speed discrepancy detected. Ghost AIS contact bearing 035 / 18 nm with no radar echo or ESM emissions.",
        "event_type": "decision",
        "scheduled_pt_ms": 300000,
        "triggered_issues": [
          "iss-sensor-anomaly"
        ],
        "target_roles": [],
        "role_descriptions": {
          "nav": "Minor speed discrepancy between GPS SOG and STW. One AIS contact bearing 035, range 18 nm with no corresponding radar echo.",
          "pwo": "No ESM emissions from bearing 035."
        }
      },
      {
        "id": "evt-t3",
        "title": "Turn 3 \u2014 Faulty Component / Increased Traffic",
        "description": "Faulty speed component identified (ETBOL 5 min). AIS traffic density increasing beyond expected baseline.",
        "event_type": "decision",
        "scheduled_pt_ms": 600000,
        "triggered_issues": [
          "iss-faulty-component"
        ],
        "target_roles": [],
        "role_descriptions": {
          "eo": "Possible faulty component identified. Resolution: Restart (5 min ETBOL).",
          "nav": "Increase in AIS contacts within sector. Commercial traffic density higher than expected baseline. Majority of contacts remain beyond visual range."
        }
      },
      {
        "id": "evt-t4",
        "title": "Turn 4 \u2014 AIS Spoofing Possible",
        "description": "First confirmed deceptive AIS track at bearing 041 / 11 nm. Component back online. Trust in AIS picture degrading.",
        "event_type": "decision",
        "scheduled_pt_ms": 900000,
        "triggered_issues": [
          "iss-ais-spoofing"
        ],
        "target_roles": [],
        "role_descriptions": {
          "nav": "New AIS contact bearing 041 at 11 nm. No vessel visible at this position.",
          "eo": "Component is back online."
        }
      },
      {
        "id": "evt-t5",
        "title": "Turn 5 \u2014 Cyber Alert & Comms Degradation",
        "description": "IBMS anomaly detected \u2014 first cyber signal, scope ambiguous. COMMS degrading: SATCOM bandwidth reduced, HF inconsistent.",
        "event_type": "decision",
        "scheduled_pt_ms": 1200000,
        "triggered_issues": [
          "iss-comms-degraded",
          "iss-cyber-alert"
        ],
        "target_roles": [],
        "role_descriptions": {
          "cyop": "Anomaly detected in IBMS.",
          "eo": "SATCOM experiencing reduced bandwidth and intermittent connectivity. Observed throughput below allocated 512 kbps baseline. HF performance degraded. Signal clarity is inconsistent. Communication with MTC is not possible with UHF due to distance."
        }
      },
      {
        "id": "evt-t6",
        "title": "Turn 6 \u2014 Cyber Analysis & Hostile Ship Spotting",
        "description": "WECDIS \u2192 INS anomalous data flow detected. Warship contact confirmed at bearing 052 / 12 nm. ESM confirms non-commercial emissions.",
        "event_type": "decision",
        "scheduled_pt_ms": 1500000,
        "triggered_issues": [
          "iss-hostile-contact"
        ],
        "target_roles": [],
        "role_descriptions": {
          "cyop": "Analysis indicates anomalous data flow originating from WECDIS towards the INS. Effects are not yet fully determined.",
          "nav": "New AIS contact bearing 052, range 12 nm. Visual silhouette indicates warship profile.",
          "pwo": "ESM detects non-commercial radar emissions at bearing 052. Emission profile not consistent with merchant vessels."
        }
      },
      {
        "id": "evt-t7",
        "title": "Turn 7 \u2014 AAW Radar Malfunction",
        "description": "AAW radar online but tracks flickering \u2014 same symptom as pre-departure maintenance issue.",
        "event_type": "decision",
        "scheduled_pt_ms": 1800000,
        "triggered_issues": [
          "iss-aaw-malfunction"
        ],
        "target_roles": [],
        "role_descriptions": {
          "aawo": "Air surveillance radar online. Multiple tracks are flickering like last time."
        }
      },
      {
        "id": "evt-t8",
        "title": "Turn 8 \u2014 Air Threat Warning",
        "description": "MTC reports hostile aircraft inbound \u2014 ETA 15 min. AAW radar still not operational.",
        "event_type": "decision",
        "scheduled_pt_ms": 2100000,
        "triggered_issues": [
          "iss-air-threat"
        ],
        "target_roles": [],
        "role_descriptions": {
          "aawo": "Report via MTC (C2 system): Hostile aircraft approaching area (ETA: 15 min).",
          "eo": "Reboot could fix the AAW issue (1 min ETBOL)."
        }
      },
      {
        "id": "evt-t9",
        "title": "Turn 9 \u2014 Hostile Salvo",
        "description": "3 incoming missiles detected. AAW radar restored. Target out of gun range. WECDIS attack unresolved.",
        "event_type": "decision",
        "scheduled_pt_ms": 2400000,
        "triggered_issues": [
          "iss-under-attack"
        ],
        "target_roles": [],
        "role_descriptions": {
          "nav": "3 incoming missiles visually detected.",
          "eo": "AAW radar is back online.",
          "pwo": "Target is out of gun range."
        }
      },
      {
        "id": "evt-t10",
        "title": "Turn 10 \u2014 First Blood",
        "description": "One missile intercepted. Two detonated nearby \u2014 CIWS FWD and missile launcher lost. HF antenna disabled. Target now in gun range.",
        "event_type": "decision",
        "scheduled_pt_ms": 2700000,
        "triggered_issues": [
          "iss-damage-first-hit"
        ],
        "target_roles": [],
        "role_descriptions": {
          "eo": "FWD CIWS: non-operational (ETBOL: 2 hours). Missiles launcher: non-operational (ETBOL: 5 hours). 1 HF antenna was disabled (unable to repair).",
          "pwo": "Target now in gun range.",
          "nav": "Missiles (counterattack) missed the target. No evidence of hostile manoeuvre to evade."
        }
      },
      {
        "id": "evt-t11",
        "title": "Turn 11 \u2014 Cyber Analysis & Surface Tracking Malfunction",
        "description": "Cyber-attack confirmed \u2014 speed feed corrupted across all systems. Surface tracking radar unstable. Manual targeting reduces effective gun range.",
        "event_type": "decision",
        "scheduled_pt_ms": 3000000,
        "triggered_issues": [
          "iss-cyber-confirmed",
          "iss-surface-tracking-degraded"
        ],
        "target_roles": [],
        "role_descriptions": {
          "cyop": "Analysis indicates a cyber-attack vector resulting in feeding all systems with wrong speed value. Option 1: Disconnect WECDIS and restart INS (ETBOL: 1 min) \u2014 WECDIS not available. Option 2: Restore WECDIS and restart INS (ETBOL 30 min) \u2014 WECDIS available.",
          "pwo": "Target within the effective gun range. Surface tracking radar is unable to achieve a stable lock. Manual targeting reduces effective engagement envelope (reduced gun effective range)."
        }
      },
      {
        "id": "evt-t12",
        "title": "Turn 12 \u2014 New Cyber Alert",
        "description": "AAW radar identified as cyber-attack source targeting surface tracking. Hostile aircraft ETA 10 min. Target 10 min from effective gun range.",
        "event_type": "decision",
        "scheduled_pt_ms": 3300000,
        "triggered_issues": [
          "iss-aaw-attack-source"
        ],
        "target_roles": [],
        "role_descriptions": {
          "cyop": "Malicious activity confirmed originating from AAW radar processing module toward surface tracking radar. Can affect tracking capability. Originated by the 'faulty' AAW radar component.",
          "aawo": "Report via MTC (C2 system): Hostile aircraft approaching area (ETA: 10 min).",
          "pwo": "Target is still out of effective gun range with manual tracking. 10 min to be in range.",
          "eo": "INS functioning correctly. Speed inputs verified across systems."
        }
      },
      {
        "id": "evt-t13",
        "title": "Turn 13 \u2014 Hard Choices",
        "description": "AAW isolation restores surface tracking immediately. Hostile aircraft ETA 8 min. Surface threat must be neutralised first.",
        "event_type": "decision",
        "scheduled_pt_ms": 3600000,
        "triggered_issues": [],
        "target_roles": [],
        "role_descriptions": {
          "cyop": "AAW originated attack resolution options: Option 1: Restore AAW radar from backup (ETBOL: 30 min). Full recovery by replacing the component from storage and flashing clean firmware. Option 2: Isolate AAW radar: ETBOL < 1 min. AAW radar unavailable while isolated. Surface tracking stability restored immediately.",
          "aawo": "Report via MTC (C2 system): Hostile aircraft approaching area (ETA: 8 min)."
        }
      },
      {
        "id": "evt-t14",
        "title": "Turn 14 \u2014 Ship Neutralised \u2014 AAW Threat Focus",
        "description": "Hostile vessel neutralised. Surface threat eliminated. Air threat unresolved \u2014 AAW reconnection restores air picture.",
        "event_type": "decision",
        "scheduled_pt_ms": 3900000,
        "triggered_issues": [],
        "target_roles": [],
        "role_descriptions": {
          "nav": "Gun engagement achieved effective impact on hostile vessel. Target exhibiting loss of manoeuvrability.",
          "pwo": "No further ESM emissions detected from hostile unit. Surface threat assessed as neutralised."
        }
      },
      {
        "id": "evt-t15",
        "title": "Turn 15 \u2014 Happy Ending",
        "description": "Hostile aircraft intercepted by friendly forces. All threats neutralised. Exercise complete \u2014 debrief to follow.",
        "event_type": "decision",
        "scheduled_pt_ms": 4200000,
        "triggered_issues": [],
        "target_roles": [],
        "role_descriptions": {}
      }
    ],
